#gmail com @ e sem
gmail_com = [gmail for gmail in gmail_sujos if "@" in gmail]
print(f"Quantidades de gmail com o @: {len(gmail_com)}")

gmail_sem = [gmail for gmail in gmail_sujos if not "@" in gmail]
print(f"Quantidades de gmail sem o @: {len(gmail_sem)}")

#vamos trabalhar e  fazer uma limpeza mais limpa dos gmails
gmail_com_caracteres_especial = []
gmail_com_letras = []
gmail_com_letras_com = []
gmail_com_letras_sem = []

for gmail in gmail_com:

    if gmail.startswith(letras) and gmail.endswith(".com"):
        gmail_com_letras_com.append(gmail)

    if gmail.startswith(letras) and not gmail.endswith(".com"):
        gmail_com_letras_sem.append(gmail)


    if gmail.startswith(letras):
        gmail_com_letras.append(gmail)


    else:
        gmail_com_caracteres_especial.append(gmail)


print(f" tamanho de gmails com letras normais no inicio: {len(gmail_com_letras)}")
